const listHealthSessions = `-- name: ListHealthSessions :many
SELECT s.id, s.title, s.created_at, b.kind AS provider,
       s.project_id AS session_project_id, t.project_id AS task_project_id,
       a.id AS attempt_id, t.id AS task_id, t.title AS task_title
FROM sessions AS s
JOIN agent_bindings AS b ON b.session_id = s.id
LEFT JOIN task_attempts AS a ON a.session_id = s.id
LEFT JOIN tasks AS t ON t.id = a.task_id
WHERE s.user_id = $1::text
  AND (s.created_at > $2::timestamptz
       OR EXISTS (SELECT 1 FROM deliveries AS d WHERE d.session_id = s.id AND d.created_at > $2::timestamptz)
       OR s.id = ANY($3::text[]))
  AND ($4::text IS NULL
       OR CASE WHEN a.id IS NULL THEN s.project_id ELSE t.project_id END = $4)
  AND ($5::text IS NULL OR t.id = $5)
  AND ($6::text IS NULL OR s.id = $6)
  AND ($7::text IS NULL OR a.id = $7)
  AND ($8::text IS NULL OR b.kind = $8)
ORDER BY s.created_at DESC, s.id
LIMIT 501
`

